  if(tg.skip === true){ return; }
  if(this._isArray(tg)){
    if(idx<=tg.length){
      if(!tg.inFlight){
        if(tg["tearDown"]){ tg.tearDown(this); }
        doh._groupFinished(groupName, !tg.failures);
