    }
    if(!idx){
      tg.inFlight = 0;
      tg.iterated = false;
      tg.failures = 0;
    }
    doh._groupStarted(groupName);
    if(!idx){
      this._setupGroupForRun(groupName, idx);
      if(tg["setUp"]){ tg.setUp(this); }
    }
    for(var y=(idx||0); y<tg.length; y++){
      doh._runFixture(groupName, tg[y]);
